cd /Users/bmw/git/cluster-template; git switch -q -c buildkite-performance-pipeline main; cat > buildkite/performance-step.sh <<'EOF'
#!/bin/sh
# Runs inside an agent-stack-k8s job pod (alpine). Pipeline step defined in
# buildkite/pipeline.tf; checkout is skipped because Buildkite can't clone
# entire:// — we exchange the job's OIDC token for an Entire session instead.
set -eu

apk add --no-cache curl jq git >/dev/null

# 1. Job OIDC token -> Entire service-account session.
oidc="$(buildkite-agent oidc request-token --audience "$ENTIRE_AUDIENCE")"
ENTIRE_TOKEN="REDACTED"$ENTIRE_TOKEN_URL" \
  -d grant_type=urn:ietf:params:oauth:grant-type:token-exchange \
  -d subject_token_type=urn:ietf:params:oauth:token-type:jwt \
  -d "subject_token=REDACTED \
  -d "resource=$ENTIRE_RESOURCE" \
  -d scope=entire:sa-session | jq -r .access_token)"

# 2. Clone over smart-HTTP. Use the chopper host directly: the main host 307s
#    to it and clients drop the Authorization header across the redirect.
git -c "http.extraHeader=Authorization: Bearer $ENTIRE_TOKEN" \
  clone --depth 1 "$ENTIRE_REPO_URL" /tmp/src
cd /tmp/src

# 3. Dagger CLI (matches the engine version) against the persistent engine.
curl -fsSL https://dl.dagger.io/dagger/install.sh \
  | DAGGER_VERSION="$DAGGER_VERSION" BIN_DIR=/usr/local/bin sh
export _EXPERIMENTAL_DAGGER_RUNNER_HOST="$DAGGER_ENGINE_HOST"
dagger check
EOF
cat > buildkite/pipeline.tf <<'EOF'
# Step logic lives in performance-step.sh. Buildkite interpolates $VAR in
# pipeline settings, so every $ is doubled to reach the pod untouched.
resource "buildkite_pipeline" "performance" {
  name           = "performance"
  description    = "Dagger CI for the Entire-hosted performance repo"
  repository     = var.performance_repo_url
  default_branch = "main"
  cluster_id     = buildkite_cluster.sailing.id

  steps = yamlencode({
    steps = [{
      label    = ":dagger: dagger check"
      key      = "check"
      agents   = { queue = buildkite_cluster_queue.kubernetes.key }
      commands = [replace(file("${path.module}/performance-step.sh"), "$", "$$")]
      env = {
        ENTIRE_AUDIENCE    = "https://us.auth.entire.io/api/authz/sts"
        ENTIRE_TOKEN_URL   = "https://us.auth.entire.io/oauth/token"
        ENTIRE_RESOURCE    = var.entire_service_account_id
        ENTIRE_REPO_URL    = var.performance_repo_url
        DAGGER_VERSION     = var.dagger_version
        DAGGER_ENGINE_HOST = "tcp://dagger-engine.buildkite.svc.cluster.local:1234"
      }
      plugins = [{
        kubernetes = {
          checkout = { skip = true }
          podSpec = {
            containers = [{
              image   = "alpine:3.22"
              command = ["sh", "-c", "$${BUILDKITE_COMMAND}"]
            }]
          }
        }
      }]
    }]
  })
}
EOF
cat >> buildkite/variables.tf <<'EOF'

variable "performance_repo_url" {
  description = "Direct (chopper) smart-HTTP URL of the Entire performance repo"
  type        = string
  default     = "https://chopper.aws-us-east-2.entire.io/et/winstead-io/performance"
}

variable "entire_service_account_id" {
  description = "Entire service account (winstead-io/buildkite) the job OIDC token is exchanged for"
  type        = string
  default     = "svc_01M6S886VDXSJ8ZCCZDH6KQ3QA"
}

variable "dagger_version" {
  description = "Dagger CLI version; must match the engine chart in kubernetes/apps/buildkite/dagger-engine"
  type        = string
  default     = "v1.0.0-beta.25"
}
EOF
cat >> buildkite/outputs.tf <<'EOF'

output "performance_pipeline_url" {
  value = buildkite_pipeline.performance.web_url
}
EOF
cd buildkite && tofu fmt 2>&1; tofu validate 2>&1 | tail -15

